var t=238;var a=[{id:`cooking-238-01`,theoryId:238,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which nutrient requires particular planning in an entirely vegan diet?`,ua:`Яка поживна речовина потребує особливої уваги в повністю веганському раціоні?`},explanation:{en:`Reliable B12 sources for vegans generally include fortified foods or appropriate supplements.`,ua:`Надійними джерелами B12 для веганів зазвичай є збагачені продукти чи відповідні добавки.`},options:[{id:`a`,text:{en:`Table starch`,ua:`Харчовий крохмаль`}},{id:`b`,text:{en:`Vitamin B12`,ua:`Вітамін B12`}},{id:`c`,text:{en:`Chlorophyll`,ua:`Хлорофіл`}}],answer:{optionIds:[`b`]}},{id:`cooking-238-02`,theoryId:238,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`A varied plant-based diet can provide protein, but vitamin B12 needs a reliable source.`,ua:`Різноманітний рослинний раціон може забезпечувати білок, але потребує надійного джерела вітаміну B12.`},explanation:{en:`Protein can come from legumes, grains and soy foods; B12 availability is a separate issue.`,ua:`Білок можна отримувати з бобових, круп та соєвих продуктів; забезпечення B12 є окремим питанням.`},answer:{value:!0}},{id:`cooking-238-03`,theoryId:238,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match plant-based nutrition concerns to appropriate food strategies.`,ua:`Поєднайте питання рослинного харчування з відповідними харчовими підходами.`},explanation:{en:`Balanced vegan meal planning considers multiple essential nutrients.`,ua:`Планування збалансованого веганського раціону враховує кілька важливих поживних речовин.`},leftItems:[{id:`l1`,text:{en:`Protein`,ua:`Білок`}},{id:`l2`,text:{en:`Vitamin B12`,ua:`Вітамін B12`}},{id:`l3`,text:{en:`Non-heme iron`,ua:`Негемове залізо`}}],rightItems:[{id:`r2`,text:{en:`Fortified foods or appropriate supplements`,ua:`Збагачені продукти чи відповідні добавки`}},{id:`r1`,text:{en:`Legumes, tofu, tempeh, nuts, and seeds`,ua:`Бобові, тофу, темпе, горіхи й насіння`}},{id:`r3`,text:{en:`Pair plant iron sources with vitamin-C-rich foods`,ua:`Поєднувати рослинні джерела заліза з продуктами, багатими на вітамін C`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-238-04`,theoryId:238,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You design a fully plant-based week-long menu. What is the strongest approach?`,ua:`Ви складаєте повністю рослинне меню на тиждень. Який підхід найкращий?`},explanation:{en:`Diet quality depends on food variety and essential nutrient coverage.`,ua:`Якість раціону залежить від різноманітності та забезпечення необхідних речовин.`},options:[{id:`a`,text:{en:`Plan varied protein sources and reliable B12, with attention to iron, calcium, iodine, and vitamin D`,ua:`Планувати різноманітні джерела білка та надійний B12 з увагою до заліза, кальцію, йоду й вітаміну D`}},{id:`b`,text:{en:`Use only lettuce for every meal`,ua:`Готувати лише листя салату на кожен прийом їжі`}},{id:`c`,text:{en:`Assume all vegan foods have identical nutritional profiles`,ua:`Вважати всі веганські продукти однаковими за поживністю`}}],answer:{optionIds:[`a`]}},{id:`cooking-238-05`,theoryId:238,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which foods can play useful roles in a vegan menu?`,ua:`Які продукти можуть бути корисними у веганському меню?`},explanation:{en:`Use verified nutrient sources instead of assuming arbitrary foods supply B12.`,ua:`Потрібні перевірені джерела нутрієнтів, а не припущення, що будь-яка їжа забезпечує B12.`},options:[{id:`a`,text:{en:`Beans and lentils`,ua:`Квасоля й сочевиця`}},{id:`b`,text:{en:`Fortified plant drinks when suitable`,ua:`Збагачені рослинні напої за потреби`}},{id:`c`,text:{en:`Unverified wild mushrooms as a guaranteed B12 source`,ua:`Невідомі дикі гриби як гарантоване джерело B12`}},{id:`d`,text:{en:`Tofu and tempeh`,ua:`Тофу та темпе`}}],answer:{optionIds:[`a`,`b`,`d`]}}];var n={theoryId:238,exercises:a};export{n as default,a as exercises,t as theoryId};